<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,computed,nextTick} from 'vue'
import {dashboard,usable} from '../store'
import {lyrics,activeLine,toggleLyrics,loadLyrics,changeOffset,syncLyrics,userScroll,lyricScroll,centerLine,stopLyrics} from '../composables/useLyrics'
import {player} from '../composables/usePlayback'
import {t} from '../composables/useLocale'
const content=ref<HTMLElement|null>(null),disabled=computed(()=>!dashboard.connected||lyrics.loading||lyrics.timingBusy||!lyrics.lines.length)
let observer:ResizeObserver|undefined
function outside(event:Event){if(!(event.target as HTMLElement)?.closest?.('#lyrics-timing-controls'))lyrics.menu=false}
function escape(event:KeyboardEvent){if(event.key==='Escape'&&lyrics.menu){lyrics.menu=false;document.getElementById('lyrics-timing-toggle')?.focus()}}
function restore(){void nextTick(centerLine)}
onMounted(()=>{document.addEventListener('click',outside);document.addEventListener('keydown',escape);window.addEventListener('resize',restore);window.addEventListener('pageshow',restore);observer=new ResizeObserver(restore);if(content.value)observer.observe(content.value)})
onBeforeUnmount(()=>{stopLyrics();observer?.disconnect();document.removeEventListener('click',outside);document.removeEventListener('keydown',escape);window.removeEventListener('resize',restore);window.removeEventListener('pageshow',restore)})
</script>
<template><section id="lyrics-panel" class="lyrics-panel" :hidden="!lyrics.open||player.choices" aria-labelledby="lyrics-heading"><div class="section-top"><h2 id="lyrics-heading">{{ lyrics.heading||t('m0141') }}</h2><button id="lyrics-close" type="button" :aria-label="t('m0321')" @click="toggleLyrics(false)">{{ t('m0118') }}</button></div><p id="lyrics-status" class="hint" role="status" aria-live="polite">{{ lyrics.status }}</p><button id="lyrics-retry" type="button" :hidden="!lyrics.retry" :disabled="!usable||lyrics.loading" @click="loadLyrics(lyrics.retryQuery)">{{ t('m0609') }}</button><div id="lyrics-timing-controls" class="lyrics-timing-controls" :hidden="!lyrics.lines.length||!lyrics.video"><button id="lyrics-timing-toggle" type="button" :aria-expanded="lyrics.menu" aria-controls="lyrics-timing-menu" @click="lyrics.menu=!lyrics.menu">{{ t('m0611') }} <span aria-hidden="true">▾</span></button><div id="lyrics-timing-menu" class="lyrics-timing-menu" role="group" :aria-label="t('m0611')" :hidden="!lyrics.menu"><button id="lyrics-minus" type="button" :disabled="disabled" @click="changeOffset('adjust',{delta:-.5})">{{ t('m0322') }}</button><button id="lyrics-plus" type="button" :disabled="disabled" @click="changeOffset('adjust',{delta:.5})">{{ t('m0323') }}</button><button id="lyrics-sync" type="button" :disabled="disabled" @click="syncLyrics">{{ t(lyrics.syncArmed?'m0156':'m0142') }}</button><button id="lyrics-reset" type="button" :disabled="disabled" @click="changeOffset('reset')">{{ t('m0324') }}</button><p id="lyrics-sync-prompt" class="hint" :hidden="!lyrics.syncArmed">{{ t('m0157')+(lyrics.lines.find(line=>line.text.trim())?.text||'')+t('m0158') }}</p></div></div><div id="lyrics-content" ref="content" class="lyrics-content" :class="{'plain-lyrics':!!lyrics.plain}" tabindex="0" :aria-label="t('m0325')" :aria-busy="lyrics.loading" @wheel.passive="userScroll" @touchstart.passive="userScroll" @pointerdown.passive="userScroll" @keydown="userScroll" @scroll.passive="lyricScroll"><p v-for="(line,index) in lyrics.lines" :key="index" :class="{active:index===activeLine,'current-line':index===activeLine}" :aria-current="index===activeLine?'true':undefined">{{ line.text||'♪' }}</p><template v-if="lyrics.plain">{{ lyrics.plain }}</template></div><form id="lyrics-search-form" class="lyrics-search" :hidden="!lyrics.search" @submit.prevent="loadLyrics(lyrics.query)"><label for="lyrics-query">{{ t('m0326') }}</label><input id="lyrics-query" v-model="lyrics.query" maxlength="200"><button id="lyrics-search" :disabled="!usable||lyrics.loading">{{ t('m0327') }}</button></form></section></template>
